mapper.select:
SELECT 
       FROM `diary` d LEFT JOIN `user` u ON d.user_id = u.id  d.is_public = 1  AND d.user_id = #{userId} 
            AND (d.title LIKE CONCAT('%', #{keyword},
       '%') OR d.content LIKE CONCAT('%', #{keyword}, '%')) 
        ORDER BY
       d.created_at DESC, d.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM `diary` d  d.is_public = 1  AND d.user_id = #{userId} 
            AND (d.title LIKE CONCAT('%', #{keyword},
       '%') OR d.content LIKE CONCAT('%', #{keyword}, '%'))

SELECT 
       FROM `diary` d LEFT JOIN `user` u ON d.user_id = u.id WHERE d.is_public = 1 ORDER BY
       d.like_count DESC, d.created_at DESC LIMIT #{limit}
